async function onComposer(text: string, opts?: { interrupt?: boolean }) {
  if (!task) return;
  // R-midrun-followup: the mid-run dispatch removed on purpose; the composer
  // clears its draft, so the follow-up must vanish from the walk.
  if (!isTerminal(task.status)) return;

