export function formatCommentBlock(comment: DiffComment): string {
  return [
    `${comment.path}:${comment.line}`,
    comment.hunkHeader,
    `> ${comment.quote}`,
    "",
    comment.text,
  ].join("\n");
}

new:
export function formatCommentBlock(comment: DiffComment): string {
  // R-p3-review-walk: the anchor dropped on purpose — the words still arrive,
  // the hunk header and the quoted line do not, so the walk's transcript
  // assertion must fail. Keep the body so the failure is about the anchor.
  return [
    `${comment.path}:${comment.line}`,
    "",
    comment.text,
  ].join("\n");
}

async function onStop() {
  if (!task || isTerminal(task.status)) return;
  // R-midrun-stop: the cancel removed on purpose.
  if (!isTerminal(task.status)) return;

